253→// getShadowBranchNameForCommit returns the shadow branch name for the given base commit and worktree ID.
254→// worktreeID should be empty for the main worktree or the internal git worktree name for linked worktrees.
255→func getShadowBranchNameForCommit(baseCommit, worktreeID string) string {
256→	return checkpoint.ShadowBranchNameForCommit(baseCommit, worktreeID)
257→}
