1174→func (s *ManualCommitStrategy) postCommitUpdateBaseCommitOnly(ctx context.Context, head *plumbing.Reference) {
1175→	logCtx := logging.WithComponent(ctx, "checkpoint")
1176→	worktreePath, err := paths.WorktreeRoot(ctx)
1177→	if err != nil {
1178→		return // Silent failure — hooks must be resilient
1179→	}
1180→
1181→	sessions, err := s.findSessionsForWorktree(ctx, worktreePath)
1182→	if err != nil || len(sessions) == 0 {
1183→		return
1184→	}
1185→
1186→	newHead := head.Hash().String()
1187→	for _, state := range sessions {
1188→		// Only update active sessions. Idle/ended sessions are kept around for
1189→		// LastCheckpointID reuse and should not be advanced to HEAD.
1190→		if !state.Phase.IsActive() {
1191→			continue
1192→		}
1193→		if state.BaseCommit != newHead {
1194→			logging.Debug(logCtx, "post-commit (no trailer): updating BaseCommit",
1195→				slog.String("session_id", state.SessionID),
1196→				slog.String("old_base", truncateHash(state.BaseCommit)),
1197→				slog.String("new_head", truncateHash(newHead)),
1198→			)
1199→			state.BaseCommit = newHead
1200→			if err := s.saveSessionState(ctx, state); err != nil {
1201→				logging.Warn(logCtx, "failed to update session state",
1202→					slog.String("session_id", state.SessionID),
1203→					slog.String("error", err.Error()))
1204→			}
1205→		}
1206→	}
1207→}
1208→
1209→// truncateHash safely truncates a git hash to 7 chars for logging.
1210→func truncateHash(h string) string {
1211→	if len(h) > 7 {
1212→		return h[:7]
1213→	}
1214→	return h
1215→}
1216→
1217→// filterSessionsWithNewContent returns sessions that have new transcript content
1218→// beyond what was already condensed.
1219→// Computes the staged files list once and reuses it across all sessions to avoid
1220→// redundant `git diff --cached` calls (previously called up to 3 times per session).
1221→func (s *ManualCommitStrategy) filterSessionsWithNewContent(ctx context.Context, repo *git.Repository, sessions []*SessionState) []*SessionState {
1222→	var result []*SessionState
1223→
1224→	// Compute staged files once for all sessions.
1225→	// On error, pass nil — sessionHasNewContent treats nil stagedFiles as
1226→	// "unavailable" and skips overlap checks, falling through to other heuristics.
1227→	stagedFiles, err := getStagedFiles(ctx)
1228→	if err != nil {
1229→		logging.Debug(logging.WithComponent(ctx, "manual-commit"),
1230→			"filterSessionsWithNewContent: getStagedFiles failed, skipping overlap checks",
1231→			slog.String("error", err.Error()),
1232→		)
1233→		stagedFiles = nil

