 67→// benchSetupPostCommitRepo creates a git repo with N sessions that have shadow branch
 68→// checkpoints, then creates a commit with the Entire-Checkpoint trailer.
 69→// Returns the repo directory path, ready for PostCommit() to run.
 70→func benchSetupPostCommitRepo(b *testing.B, phase session.Phase, sessionCount int) string {
 71→	b.Helper()
 72→
 73→	dir := b.TempDir()
 74→	// Resolve symlinks (macOS /var -> /private/var)
 75→	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
 76→		dir = resolved
 77→	}
 78→
 79→	repo, err := git.PlainInit(dir, false)
 80→	if err != nil {
 81→		b.Fatalf("git init: %v", err)
 82→	}
 83→
 84→	// Configure git user
 85→	cfg, err := repo.Config()
 86→	if err != nil {
 87→		b.Fatalf("config: %v", err)
 88→	}
 89→	cfg.User.Name = "Bench User"
 90→	cfg.User.Email = "bench@example.com"
 91→	if err := repo.SetConfig(cfg); err != nil {
 92→		b.Fatalf("set config: %v", err)
 93→	}
 94→
 95→	// Create initial files and commit
 96→	wt, err := repo.Worktree()
 97→	if err != nil {
 98→		b.Fatalf("worktree: %v", err)
 99→	}
100→
101→	// Create multiple files to make file overlap checks realistic
102→	for i := range 5 {
103→		name := fmt.Sprintf("src/file_%d.go", i)
104→		abs := filepath.Join(dir, name)
105→		if err := os.MkdirAll(filepath.Dir(abs), 0o755); err != nil {
106→			b.Fatalf("mkdir: %v", err)
107→		}
108→		content := fmt.Sprintf("package main\nfunc f%d() {}\n", i)
109→		if err := os.WriteFile(abs, []byte(content), 0o644); err != nil {
110→			b.Fatalf("write: %v", err)
111→		}
112→		if _, err := wt.Add(name); err != nil {
113→			b.Fatalf("add: %v", err)
114→		}
115→	}
116→
117→	if _, err := wt.Commit("initial commit", &git.CommitOptions{
118→		Author: &object.Signature{Name: "Bench", Email: "bench@test.com", When: time.Now()},
119→	}); err != nil {
120→		b.Fatalf("commit: %v", err)
121→	}
122→
123→	s := &ManualCommitStrategy{}
124→
